// GENERATED by tools/recompile.mjs: the Donkey Kong cartridge's tables and
// graphics (every byte no instruction occupies), by address. The code itself
// is translated in dkRecomp.mjs; the cartridge image is not included.

export const ROM_DATA = [
  [0xf7a3, '9d'],
  [0xf900, '30507090b0d0d0d0ffff'],
  [0xf94d, ''],
  [0xfa00, '0031087fff8dff036a9a2d8a85540001020304050f0a0f0a0f0000000200000002000000020000000200000002fd55fd55ff0000000800000008000000080000000800000008ff54ff54ff0000000800000008000000080000000800000008000000000000000000000000000000000000fd55fd55fd0000000800000008000000080000000800000008'],
  [0xfacd, ''],
  [0xfcff, ''],
  [0xfdf8, ''],
];

// 4K image with the data in place; code addresses read as 0
export function romImage() {
  const rom = new Uint8Array(4096);
  for (const [at, hexBytes] of ROM_DATA) {
    for (let i = 0; i < hexBytes.length / 2; i += 1) rom[(at + i) & 0xfff] = parseInt(hexBytes.substr(i * 2, 2), 16);
  }
  return rom;
}
